arguments.command:
cd /dateutil && python -c "
from dateutil.parser import parse
for s in ['10 m 30','10 h 30','10 m 30 s','10 h 30 m 15','10 m 30.5']:
    try:
        print(repr(s), parse(s, default=__import__('datetime').datetime(2000,1,1)))
    except Exception as e:
        print(repr(s), 'EXC', e)
"
